<?php $titulo='Monitoramento'; $modulo='monitoramento'; ?>
<div class="d-flex justify-content-between align-items-center mb-3"><div><h4 class="mb-1">Tráfego observado</h4><div class="text-muted small">Amostras importadas do access.log do Squid · <?=h($periodos[$f['periodo']??'24h'])?></div><small class="text-muted" id="estadoColeta">Coleta pausada</small></div><div class="d-flex gap-2"><button class="btn btn-outline-secondary btn-sm" id="btnPausar" type="button"><i class="bi bi-pause-fill"></i> Pausar</button><button class="btn btn-outline-primary btn-sm" id="btnAtualizar" type="button"><i class="bi bi-arrow-clockwise"></i> Atualizar agora</button></div></div>
<form class="card card-body mb-3" method="get"><div class="row g-2 align-items-end"><div class="col-md-2"><label class="form-label">Período</label><select name="periodo" class="form-select"><?php foreach($periodos as $k=>$nome):?><option value="<?=h($k)?>" <?=($f['periodo']??'24h')===$k?'selected':''?>><?=h($nome)?></option><?php endforeach;?></select></div><div class="col-md-2"><label class="form-label">IP</label><input class="form-control" name="ip" value="<?=h($f['ip']??'')?>" placeholder="192.168.1.20"></div><div class="col-md-2"><label class="form-label">Grupo (IP exato)</label><select class="form-select" name="grupo"><option value="">Todos</option><?php foreach($grupos as $g):?><option value="<?=h($g['id'])?>" <?=($f['grupo']??'')==(string)$g['id']?'selected':''?>><?=h($g['nome'])?></option><?php endforeach;?></select></div><div class="col-md-2"><label class="form-label">Domínio/usuário</label><input class="form-control" name="busca" value="<?=h($f['busca']??'')?>"></div><div class="col-md-1"><label class="form-label">Protocolo</label><select name="protocolo" class="form-select"><option value="">Todos</option><?php foreach(['http','https'] as $p):?><option <?=($f['protocolo']??'')===$p?'selected':''?>><?=$p?></option><?php endforeach;?></select></div><div class="col-md-2"><label class="form-label">Decisão</label><select name="decisao" class="form-select"><option value="">Todas</option><option value="permitido" <?=($f['decisao']??'')==='permitido'?'selected':''?>>OK</option><option value="bloqueado" <?=($f['decisao']??'')==='bloqueado'?'selected':''?>>Negado</option></select></div><div class="col-md-1"><button class="btn btn-primary w-100">Filtrar</button></div></div></form>
<div class="alert alert-info py-2 small">Conexões ativas vêm dos sockets TCP do kernel. Histórico e volume vêm do access.log do Squid; upload é o tamanho da requisição HTTP informado pelo Squid, não todo o tráfego da rede.</div>
<ul class="nav nav-tabs mb-3" role="tablist"><li class="nav-item"><button type="button" class="nav-link active" data-monitor-view="conexoes">Conexões ativas</button></li><li class="nav-item"><button type="button" class="nav-link" data-monitor-view="historico">Histórico de acessos</button></li><li class="nav-item"><button type="button" class="nav-link" data-monitor-view="bloqueios">Bloqueios</button></li><li class="nav-item"><a class="nav-link" href="/internet">Sessões de usuários</a></li></ul>
<div id="monitorConexoes"><div class="card"><div class="card-header d-flex justify-content-between"><strong>Sockets estabelecidos no proxy</strong><span class="small text-muted">Consulta direta ao kernel</span></div><div class="table-responsive"><table class="table table-hover mb-0"><thead class="table-light"><tr><th>IP / equipamento / usuário</th><th>Porta cliente</th><th>Listener Squid</th><th>Estado</th></tr></thead><tbody id="tabelaConexoes"><tr><td colspan="4" class="text-center text-muted py-4">Consultando sockets ativos…</td></tr></tbody></table></div><div id="estadoConexoes" class="card-footer small text-muted"></div></div></div>
<div id="monitorHistorico" class="d-none">
<div class="card"><div class="table-responsive"><table class="table table-hover align-middle mb-0"><thead class="table-light"><tr><th>Horário</th><th>IP / equipamento / usuário</th><th>Destino</th><th>Destino IP</th><th>Protocolo</th><th>Interface</th><th>Decisão Squid</th><th class="text-end">Download</th><th class="text-end">Upload</th></tr></thead><tbody id="tabelaAcessos"><?php if(!$acessos):?><tr><td colspan="9" class="text-center text-muted py-4">Sem registros na janela selecionada. Confira se o Squid está instalado e o importador está ativo.</td></tr><?php endif;?><?php foreach($acessos as $a):$blocked=str_contains($a['status'],'DENIED')||str_contains($a['status'],'BLOCKED');?><tr><td><?=h($a['ocorrido_em'])?></td><td><span class="font-monospace"><?=h($a['ip'])?></span><div class="small"><?=h($a['hostname']??'equipamento não identificado')?></div><div class="small text-muted"><?=h($a['email']??'sem login')?><?=!empty($a['mac'])?' · '.h($a['mac']):''?></div></td><td><?=h($a['dominio'])?><?php if($a['porta']):?><small class="text-muted">:<?=h($a['porta'])?></small><?php endif;?></td><td class="font-monospace"><?=h($a['destino_ip']??'indisponível na fonte')?></td><td><?=h(strtoupper($a['protocolo']??'—'))?></td><td><?=h($a['interface_rede']??'indisponível na fonte')?></td><td><span class="badge bg-<?=$blocked?'danger':'success'?>"><?=h($a['status'])?></span></td><td class="text-end"><?=formatar_bytes((int)$a['bytes'])?></td><td class="text-end"><?=$a['request_bytes']===null?'sem dados':formatar_bytes((int)$a['request_bytes'])?></td></tr><?php endforeach;?></tbody></table></div></div>
</div>
<script>
(()=>{const body=document.getElementById('tabelaAcessos'),state=document.getElementById('estadoColeta'),pause=document.getElementById('btnPausar'),filters=document.querySelector('form[method="get"]'),connBody=document.getElementById('tabelaConexoes'),connState=document.getElementById('estadoConexoes');let active=true,busy=false;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const bytes=n=>{n=Number(n)||0;if(n<1024)return n+' B';const u=['KB','MB','GB','TB'];let i=-1;do{n/=1024;i++;}while(n>=1024&&i<u.length-1);return n.toFixed(1)+' '+u[i];};
async function refresh(){if(busy)return;busy=true;state.textContent='Consultando dados do Squid e kernel…';try{const p=new URLSearchParams(new FormData(filters));p.set('json','1');const res=await fetch('/monitoramento?'+p.toString(),{cache:'no-store',headers:{'Accept':'application/json'}});if(!res.ok)throw Error();const data=await res.json();body.innerHTML=data.acessos.length?data.acessos.map(a=>{const denied=/DENIED|BLOCKED/.test(a.status||'');return `<tr><td>${esc(a.ocorrido_em)}</td><td><span class="font-monospace">${esc(a.ip)}</span><div class="small">${esc(a.hostname||'equipamento não identificado')}</div><div class="small text-muted">${esc(a.email||'sem login')}${a.mac?' · '+esc(a.mac):''}</div></td><td>${esc(a.dominio)}${a.porta?`<small class="text-muted">:${esc(a.porta)}</small>`:''}</td><td class="font-monospace">${esc(a.destino_ip||'indisponível na fonte')}</td><td>${esc((a.protocolo||'—').toUpperCase())}</td><td>${esc(a.interface_rede||'indisponível na fonte')}</td><td><span class="badge bg-${denied?'danger':'success'}">${esc(a.status)}</span></td><td class="text-end">${bytes(a.bytes)}</td><td class="text-end">${a.request_bytes===null?'sem dados':bytes(a.request_bytes)}</td></tr>`}).join(''):'<tr><td colspan="9" class="text-center text-muted py-4">Sem registros na janela selecionada.</td></tr>';const c=data.conexoes||{disponivel:false,motivo:'Dados de conexão indisponíveis.',conexoes:[]};connBody.innerHTML=c.disponivel&&c.conexoes.length?c.conexoes.map(x=>`<tr><td><span class="font-monospace">${esc(x.ip)}</span><div class="small">${esc(x.hostname||'equipamento não identificado')}</div><div class="small text-muted">${esc(x.email||'sem sessão de usuário')}${x.mac?' · '+esc(x.mac):''}</div></td><td>${esc(x.porta_cliente)}</td><td>${esc(x.porta_proxy)}${x.porta_proxy===3129?' · HTTPS':x.porta_proxy===3128?' · HTTP interceptado':' · proxy explícito'}</td><td><span class="badge bg-success">${esc(x.estado)}</span></td></tr>`).join(''): `<tr><td colspan="4" class="text-center text-muted py-4">${esc(c.motivo)}</td></tr>`;connState.textContent=c.motivo;state.textContent='Atualizado '+new Date(data.coletado_em).toLocaleTimeString('pt-BR')+' · histórico novo após importação cron';}catch{state.textContent='Falha ao consultar; confira a sessão e o estado do banco.';connState.textContent='Falha na consulta de sockets.';}finally{busy=false;}}
document.querySelectorAll('[data-monitor-view]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-monitor-view]').forEach(x=>x.classList.toggle('active',x===b));document.getElementById('monitorConexoes').classList.toggle('d-none',b.dataset.monitorView!=='conexoes');document.getElementById('monitorHistorico').classList.toggle('d-none',b.dataset.monitorView==='conexoes');if(b.dataset.monitorView==='bloqueios'){const f=document.querySelector('select[name=decisao]');if(f){f.value='bloqueado';refresh();}}}));
if(new URLSearchParams(location.search).get('aba')==='bloqueios'){document.querySelector('[data-monitor-view=bloqueios]')?.click();}
document.getElementById('btnAtualizar').addEventListener('click',refresh);pause.addEventListener('click',()=>{active=!active;pause.innerHTML=active?'<i class="bi bi-pause-fill"></i> Pausar':'<i class="bi bi-play-fill"></i> Retomar';state.textContent=active?'Atualização retomada':'Atualização pausada';if(active)refresh();});filters.addEventListener('submit',()=>{active=true;});refresh();setInterval(()=>{if(active)refresh();},15000);})();
</script>
